	public static int longestSubarray(int[] ints)
	{
		int max = 0;
		for (int i : ints)
		{
			max = Math.max(i, max);
		}

		int count = 1;
		int maxStreak = 1;
		for (int i : ints)
		{
			if (i == max)
			{
				maxStreak = Math.max(count, maxStreak);
				count++;
				continue;
			}
			count = 1;
		}
		return maxStreak;
	}

	/**
	 * misunderstood the problem...
	 * thought the problem asked for the number with the highest bit count
	 * e.g.
	 * ints 1, 2
	 * 1 : 0001
	 * 2 : 0010
	 * returns any since both have 1 '1'-bit count and only 1 occurrence of each
	 * then thought problem wanted
	 * ints 1, 1, 2
	 * return 1 because 1 more frequent (2 occurrences) -> the longest subarray
	 * <p>
	 * very confusing problem statement
	 */
	public static int getHighestBitCountSubarray(int[] nums)
	{
		System.out.println();
		System.out.println(Arrays.toString(nums));
		HashMap<Integer, Integer> bitMap = new HashMap<>();
		HashMap<Integer, Integer> lengthMap = new HashMap<>();
		int count = 1;
		bitMap.put(nums[0], Integer.bitCount(nums[0]));
		lengthMap.put(nums[0], Math.max(lengthMap.getOrDefault(nums[0], 1), count));
		for (int i = 1; i < nums.length; i++)
		{
			count = nums[i] == nums[i - 1] ? count + 1 : 1;
			bitMap.put(nums[i], Integer.bitCount(nums[i]));
			lengthMap.put(nums[i], Math.max(lengthMap.getOrDefault(nums[i], 1), count));
		}

		int maxBits = bitMap.values().stream().max(Integer::compareTo).orElse(0);
		System.out.println(bitMap);
		System.out.println(lengthMap);
		bitMap.entrySet().removeIf(entry -> entry != null && entry.getValue() < maxBits);
		lengthMap.entrySet().removeIf(entry -> !bitMap.containsKey(entry.getKey()));
		System.out.println(bitMap);
		System.out.println(lengthMap);

		return lengthMap.entrySet().stream().max(Map.Entry.comparingByKey()).get().getValue();
	}
